import{_ as i,B as d,o as n,c as o,a,f as t,E as s,a8 as l}from"./chunks/framework.CNIpabDg.js";const y=JSON.parse('{"title":"Graphics bindings","description":"Supported guest graphics calls, checked Xila helpers, status codes, resource limits, and LVGL compatibility requirements.","frontmatter":{"layout":"doc","docType":"reference","description":"Supported guest graphics calls, checked Xila helpers, status codes, resource limits, and LVGL compatibility requirements."},"headers":[],"relativePath":"reference/graphics-bindings.md","filePath":"reference/graphics-bindings.md","lastUpdated":1793145952000}'),c={name:"reference/graphics-bindings.md"};function p(u,e,h,g,m,b){const r=d("CodeReference");return n(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[e[9]||(e[9]=a("h1",{id:"graphics-bindings",tabindex:"-1"},[t("Graphics bindings "),a("a",{class:"header-anchor",href:"#graphics-bindings","aria-label":'Permalink to "Graphics bindings"'},"​")],-1)),a("p",null,[e[0]||(e[0]=t("The ",-1)),e[1]||(e[1]=a("code",null,"xila-wasm",-1)),e[2]||(e[2]=t(" Cargo package's optional ",-1)),e[3]||(e[3]=a("code",null,"graphics",-1)),e[4]||(e[4]=t(" feature provides the supported ",-1)),e[5]||(e[5]=a("code",null,"xila_graphics_call",-1)),e[6]||(e[6]=t(" interface. Core uses LVGL 9.6. Sources: ",-1)),s(r,{repo:"applications",path:"executables/wasm/README.md"}),e[7]||(e[7]=t(" and ",-1)),s(r,{repo:"applications",path:"executables/wasm/src/host/graphics"}),e[8]||(e[8]=t(".",-1))]),e[10]||(e[10]=l('<h2 id="supported-calls" tabindex="-1">Supported calls <a class="header-anchor" href="#supported-calls" aria-label="Permalink to &quot;Supported calls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Family</th><th>Supported operations</th></tr></thead><tbody><tr><td>Windows</td><td>Creation, icon, event retrieval, pointer-aware event retrieval</td></tr><tr><td>Objects</td><td>Creation/deletion, geometry getters/setters, alignment, flex, flags, padding</td></tr><tr><td>Labels</td><td>Creation and text</td></tr><tr><td>Button matrices</td><td>Creation, map, selected button</td></tr><tr><td>Text areas</td><td>Checked text copy</td></tr><tr><td>Keyboards</td><td>Checked keyboard attachment</td></tr><tr><td>Indexed canvas</td><td>Host-owned indexed image creation and pixel/palette upload</td></tr><tr><td>Geometry</td><td>Percentage conversion, position/size, layout updates and checked grid tracks/cells</td></tr><tr><td>Local styling</td><td>RGB888 background/text/border colors, opacity, radius, border sides, text alignment and size bounds</td></tr><tr><td>Theme and fonts</td><td>Four semantic theme surfaces and six host-owned ROM font roles</td></tr></tbody></table><p>The build-time <code>GraphicsRegistry</code> exposes only host-supported Rust/C wrappers and host metadata; unsupported discovered LVGL calls are omitted from guest APIs without changing legacy catalog IDs. It writes <code>graphics_abi_inventory.json</code> under Cargo <code>OUT_DIR</code> for build-time inspection, not as runtime ABI negotiation. Following Core #488 and #489, this configuration supports <strong>133 host-dispatched calls</strong> out of 1,088 surveyed LVGL/Xila catalog entries, while 955 remain excluded. This is still a deliberately bounded LVGL subset, not full widget coverage.</p><p>Calculator exercises the basic widget subset. Pixel Painter additionally exercises pointer events, text input, keyboard attachment, and the indexed-canvas helpers. Weather still needs APIs beyond the currently supported subset.</p><p>Calls requiring arbitrary native structure layouts, guest callbacks, retained guest pointers, unrestricted native font/style pointers, raw image/asset resources, or other unsupported LVGL APIs are not exposed in the generated guest API. <strong>Chart and Line have bounded, typed adapters</strong>, not arbitrary native LVGL pointer access. If invoked by numeric ID, unsupported calls return an unsupported status. Guest memory is never interpreted as a typed host reference.</p><h2 id="expanded-widgets-and-limits" tabindex="-1">Expanded widgets and limits <a class="header-anchor" href="#expanded-widgets-and-limits" aria-label="Permalink to &quot;Expanded widgets and limits&quot;">​</a></h2><p>Core #488 introduces checked <strong>Arc</strong>, <strong>Bar</strong>, <strong>Slider</strong>, <strong>Switch</strong> and <strong>Spinner</strong> wrappers, with validated range/value/mode, orientation, state and animation parameters. Core #489 adds selected <strong>Calendar</strong>, <strong>Spinbox</strong>, <strong>Chart</strong>, <strong>Line</strong>, <strong>List</strong> and <strong>Tileview</strong> operations, plus themed <strong>Badge</strong>, <strong>Card</strong>, button variants and input error styling.</p><p>Additional limits include at most <strong>32 Calendar highlights</strong>, <strong>8 Chart series with 128 values each</strong>, <strong>128 Line points</strong>, <strong>64 List items</strong>, <strong>32 live Tileview tiles</strong>, and <strong>8,192 bytes of shared retained per-VM data</strong>. Spinbox values are restricted to ±1,000,000 with 1–10 digits. Native arrays and Chart series remain host-owned; arguments, object state and resource limits are checked before LVGL mutation. These values are for the merged ABI, not a guarantee of platform memory budgets.</p><p>Missing widget families, Calendar pressed-date events, rich Chart/List interaction, native image assets, capability/version negotiation and a full linked-size comparison remain outside the current scope.</p><h2 id="xila-specific-checked-helpers" tabindex="-1">Xila-specific checked helpers <a class="header-anchor" href="#xila-specific-checked-helpers" aria-label="Permalink to &quot;Xila-specific checked helpers&quot;">​</a></h2><p>New Xila helpers use append-only call identifiers starting at <code>0xf000</code>, separate from the generated LVGL-derived catalog. The <code>grid_fr</code> fractional-track helper uses <code>0xf006</code>; semantic local-style and font helpers use <code>0xf007</code> through <code>0xf00e</code>.</p><ul><li><code>indexed_canvas_create</code> allocates a host-owned indexed image.</li><li><code>indexed_canvas_set_pixels</code> validates and copies palette indexes and RGB888 palette entries from guest memory. No guest pointer is retained after the call.</li><li><code>window_pop_pointer_event</code> returns event-time pointer coordinates relative to the target content area together with that area&#39;s width and height. For events without pointer data, x/y are <code>i32::MIN</code> and width/height are zero.</li><li>The original <code>window_pop_event</code> contract remains unchanged.</li><li>Checked adapters also cover textarea text copying, keyboard attachment, object padding, and flag removal.</li></ul><h2 id="layout-and-styling-boundaries" tabindex="-1">Layout and styling boundaries <a class="header-anchor" href="#layout-and-styling-boundaries" aria-label="Permalink to &quot;Layout and styling boundaries&quot;">​</a></h2><p>Grid descriptor arrays are copied from guest memory, validated for sentinel termination and retained by the host while LVGL uses them. Each axis is limited to <strong>31 tracks</strong>, with <strong>512 retained grid descriptors per VM</strong> in total. Grid cell placement/span and alignment selectors are validated, as are signed geometry arguments on memory32 and memory64 hosts. Style selectors accept only recognized LVGL parts and states. A guest selects theme surfaces and font roles by IDs; it never supplies an LVGL font or style pointer.</p><h2 id="resource-limits" tabindex="-1">Resource limits <a class="header-anchor" href="#resource-limits" aria-label="Permalink to &quot;Resource limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Limit/behavior</th></tr></thead><tbody><tr><td>Issued object handles</td><td>256 per execution, including deleted handles; handles are not reused during execution.</td></tr><tr><td>Indexed-canvas pixels</td><td>65,536 host-owned pixels per VM across indexed canvases.</td></tr><tr><td>Button-map entries</td><td>64 including the sentinel.</td></tr><tr><td>NUL-terminated string</td><td>1024 bytes.</td></tr><tr><td>Retained map strings</td><td>8192 bytes per widget, including the native sentinel.</td></tr><tr><td>Map termination</td><td>Null and empty-string guest sentinels become LVGL&#39;s empty-string terminator; row separators are preserved.</td></tr></tbody></table><p>Indexed-canvas buffers remain owned by the host while their native object exists and are reclaimed after deletion or at VM teardown. Pixel Painter&#39;s 160×100 canvas consumes 16,000 indexed pixels plus its palette on the host, in addition to guest-side drawing/undo/file buffers and LVGL allocations.</p><h2 id="status-codes" tabindex="-1">Status codes <a class="header-anchor" href="#status-codes" aria-label="Permalink to &quot;Status codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td>0</td><td>Success</td></tr><tr><td>1</td><td>Invalid count</td></tr><tr><td>2</td><td>Invalid memory</td></tr><tr><td>3</td><td>Unavailable capability</td></tr><tr><td>4</td><td>Unsupported call</td></tr><tr><td>5</td><td>Invalid handle</td></tr><tr><td>6</td><td>Resource limit</td></tr><tr><td>7</td><td>Invalid value</td></tr><tr><td>8</td><td>Native failure</td></tr></tbody></table><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><p>Guest and host bindings must use the same LVGL revision and configuration. Generated LVGL call IDs do not establish a stable cross-version graphics ABI. Event transport preserves numeric codes, including window-close requests, rather than treating unknown values as valid Rust enum variants.</p><p>Guest-only applications disable <code>wasm</code>&#39;s default features and select <code>guest,graphics,memory_32</code>. <code>default_guest</code> additionally enables C wrappers and emits <code>xila_graphics.h</code> in the build output; generation does not rewrite guest source files.</p><h2 id="related-documentation" tabindex="-1">Related documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related documentation&quot;">​</a></h2><ul><li><a href="/explanation/architecture/executables/bindings.html">Graphics binding ownership</a>.</li><li><a href="/explanation/architecture/executables/pixel_painter.html">Pixel Painter</a>.</li><li><a href="/how-to/build-guest.html">Build a guest application</a>.</li><li><a href="./wasm-runtime.html">WASM runtime</a>.</li></ul>',24))])}const x=i(c,[["render",p]]);export{y as __pageData,x as default};
